package glitch

import data.glitch_lib

# Weak Encryption Algorithms
weak_algorithms := {"DES", "3DES", "RC4", "AES-128", "RSA-1024", "ECDSA-P-160", "SHA-1", "MD5", "BLOWFISH", "TWOFISH-128"}

# Inadequate Key Lengths (represented as strings to match potential attribute values)
inadequate_key_sizes := {"1024", "224", "128", "160"}

# Outdated Protocols
outdated_protocols := {"SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "TLS_1_0", "TLS_1_1"}

# Weak Cipher Suites (keyword matching)
weak_ciphers := {"CBC", "RC4", "DES", "3DES", "NULL", "EXPORT", "MD5", "SHA-1"}

# Predictable/Reused Keys (keyword matching for hardcoded/secrets)
predictable_keys := {"password123", "static_value", "hardcoded-secret", "aVeryWeakAndStaticHardcodedSecretKeyForEncryption"}

# Default/Misconfigured Encryption
misconfigured_encryption := {"DISABLED", "false", "unencrypted"}

# Outdated Standards
outdated_standards := {"FIPS_140_2", "legacy", "old_standard"}

# Common attribute names to check
crypto_attrs := {"algorithm", "encryption_algorithm", "cipher", "key_spec", "key_size", "key_length", "bits", "protocol", "protocol_version", "tls_version", "ssl_policy", "security_policy", "cipher_suite", "ciphers", "key", "secret", "salt", "nonce", "initialization_vector", "encryption_enabled", "enable_encryption", "default_encryption", "security_standard", "compliance_mode", "fips_mode", "encryption", "encryption_type", "crypto_policy"}

# Helper to check if string contains a weak pattern
contains_weak_pattern(str, patterns) {
    regex.match(sprintf("(?i).*(%s).*", [concat("|", patterns)]), str)
}

# Recursive search for Attributes containing weak crypto values in Hash or Array structures
check_nested_attributes(attrs, patterns, type_name) {
    attr := attrs[_]
    crypto_attrs[_] == attr.name
    check_value(attr.value, patterns, type_name)
}

check_value(val, patterns, type_name) {
    val.ir_type == "String"
    contains_weak_pattern(val.value, patterns)
} {
    val.ir_type == "Integer"
    # Convert integer to string to check against string patterns
    val_str := sprintf("%d", [val.value])
    contains_weak_pattern(val_str, patterns)
} {
    val.ir_type == "Hash"
    # Check keys and values inside the hash
    kv := val.value[_]
    # Check key
    check_value(kv.key, patterns, type_name)
    # Check value
    check_value(kv.value, patterns, type_name)
} {
    val.ir_type == "Array"
    # Check items inside the array
    item := val.value[_]
    check_value(item, patterns, type_name)
}

# Main Rule for CWE-326
Glitch_Analysis[result] {
    # Gather all atomic units (resources/tasks)
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check attributes within the atomic unit
    attrs := glitch_lib.all_attributes(node)

    # Check for Weak Encryption Algorithms
    check_nested_attributes(attrs, weak_algorithms, "sec_weak_encryption_algorithm")

    result := {
        "type": "sec_weak_crypt",
        "element": attrs[_],
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic algorithm detected (CWE-326)"
    }
}

